    spoon_patches = image_patch.find("spoon")

    if not bowl_patches or not spoon_patches:
        return image_patch

    bowl_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in bowl_patches]
    spoon_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in spoon_patches]

    closest_spoon_to_bowl = min(spoon_centers, key=lambda s: sum((s[i] - b[i]) ** 2 for i in range(2)))
    closest_bowl_to_spoon = min(bowl_centers, key=lambda b: sum((b[i] - s[i]) ** 2 for i in range(2)))

    if closest_spoon_to_bowl == closest_bowl_to_spoon:
        return image_patch

    if closest_spoon_to_bowl < closest_bowl_to_spoon:
        return spoon_patches[spoon_centers.index(closest_spoon_to_bowl)]
    else:
        return bowl_patches[bowl_centers.index(closest_bowl_to_spoon)]

